mapper.select:
SELECT c.id, c.no, c.warehouse_id, w.code AS warehouse_code, w.name AS warehouse_name, c.status, c.source, c.complete_time, c.remark, (SELECT COUNT(*) FROM inv_check_detail d WHERE d.check_id = c.id AND d.deleted = 0) AS line_count, (SELECT COUNT(*) FROM inv_check_detail d WHERE d.check_id = c.id AND d.deleted = 0 AND d.actual_qty IS NOT NULL) AS actual_count, (SELECT COUNT(*) FROM inv_check_detail d WHERE d.check_id = c.id AND d.deleted = 0 AND d.diff_qty IS NOT NULL AND d.diff_qty != 0) AS diff_count, c.create_time FROM inv_check c LEFT JOIN base_warehouse w ON w.id = c.warehouse_id WHERE c.deleted = 0
AND c.status = #{q.status}
AND c.warehouse_id = #{q.warehouseId}
AND c.no LIKE CONCAT('%', #{q.keyword}, '%')
ORDER BY c.id DESC
